"""Builds recommendation.json from the measured numbers in VOICE_REAL.json (no hand-typed figures)."""
import json, os
R = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
r = json.load(open(f"{R}/VOICE_REAL.json"))
H = r["asr_wer"]["headline"]; X = r["asr_wer"]["extended_samples"]; S = r["slurp"]; E = r["end_of_turn"]; T = r["cpu_timing_idle_vm"]["timing_idle_1t.json"]; PM = r["paired_modes"]
d = lambda k: H[k]["delta_pt"]
sc = S["c1_scen"]; it = S.get("c1_intent")
sl, am = E["slurp"]["tail_noise"], E["ami"]["tail_noise"]
slz = E["slurp"]["tail_zero"]
def e(o): return f"false cut {o['false_cut_before_last_word_pct']}%, latency p50 {o['lat_incl_idle_cpu_ms']['p50']:.0f} ms / p90 {o['lat_incl_idle_cpu_ms']['p90']:.0f} ms, no decision within 2.5 s {o['miss_pct']}%"
lines = []
lines.append(["ASR model:", f"keep NVIDIA Nemotron Speech Streaming EN 0.6B (NVIDIA Open Model License, commercial use permitted). Our streaming loop reproduces the card at 560 ms: LibriSpeech clean {d('ls_clean/s560'):+.2f} pt, other {d('ls_other/s560'):+.2f}, TED-LIUM {d('tedlium/s560'):+.2f} (all within 0.5 pt, n=500 each). "
              f"AMI is {d('ami/s560'):+.2f} pt at n=500 and {X['ami_big/s560']['delta_pt']:+.2f} pt at n={X['ami_big/s560']['n_utts']} (card inside our CI); Earnings-22 is {d('earnings22/s560'):+.2f} pt at n=500 and {X['earnings22_big/s560']['delta_pt']:+.2f} pt at n={X['earnings22_big/s560']['n_utts']} (we are BETTER than the card; offline mode matches it, {d('earnings22/offline'):+.2f} pt). "
              "So the strict +-0.5 pt rule is missed on AMI at n=500 (sampling: 3.6k reference words) and on Earnings-22 (in the favourable direction); nothing points to a broken loop."])
lines.append(["Chunk mode:", f"560 ms (att_context [70,6]) with a forced flush at end of input. On identical utterances 160 ms is worse than 560 ms in every set ("
              + ", ".join(f"{k} {v['delta_s160_minus_s560_pt']:+.2f}" for k, v in PM.items()) + " pt; the paired 95% interval excludes zero in " + ", ".join(k for k, v in PM.items() if v['delta_s160_minus_s560_ci95_pt'][0] > 0.004) + " and touches zero in " + ", ".join(k for k, v in PM.items() if abs(v['delta_s160_minus_s560_ci95_pt'][0]) <= 0.004) + "), the same ordering as the card. On this CPU, bf16, one thread: "
              f"560 ms chunks take {T['nemotron_bf16_s560_chunk_ms']['p50']:.0f} ms per 560 ms of audio (0.44x real time); 160 ms chunks take {T['nemotron_bf16_s160_chunk_ms']['p50']:.0f} ms per 160 ms (1.4x, not real time). "
              "Use offline mode for whole-file uploads. The flush is needed: the card's loop drops the last partial chunk (see the ablation)."])
lines.append(["End of turn:", "default = an explicit end signal (client closes the stream, push-to-talk, file upload): no wait, no false cuts. For a live microphone use Silero VAD + Smart Turn v3.2 (BSD-2, CPU, "
              f"{T['smart_turn_ms']['total_p50']:.0f} ms per call on one idle thread) with stop_secs = 0.5 s as the locked default: SLURP {e(sl['st_0.5'])}; AMI {e(am['st_0.5'])}. "
              f"A faster setting (stop 0.2 s) trades latency for cuts: SLURP {e(sl['st_0.2'])}; AMI {e(am['st_0.2'])}. Silero alone at 0.5 s is worse than with Smart Turn on conversational speech (AMI false cut {am['vad_0.5']['false_cut_before_last_word_pct']}% vs {am['st_0.5']['false_cut_before_last_word_pct']}%)."])
lines.append(["Latency budget (arithmetic across machines):", f"live microphone with Silero + Smart Turn at 0.5 s: about {sl['st_0.5']['lat_incl_idle_cpu_ms']['p50']:.0f} ms p50 to the end-of-turn decision (measured here, SLURP) + about 72 ms ASR flush + about 28 ms C1 (both L4 p50 from the 17 Oct synthetic-audio step) = roughly 0.9 s after the user stops; with an explicit end signal only the last two terms remain (about 100 ms). On CPU instead of the L4 the ASR flush chunk is {T['nemotron_bf16_s560_chunk_ms']['last_flush_chunk_p50']:.0f} ms (bf16, one thread) / {r['cpu_timing_idle_vm']['timing_idle_4t.json']['nemotron_bf16_s560_chunk_ms']['last_flush_chunk_p50']:.0f} ms (4 threads)."])
lines.append(["Parakeet Realtime EOU 120M:", f"not recommended as the primary method. It cuts least (SLURP {sl['eou']['false_cut_before_last_word_pct']}%, AMI {am['eou']['false_cut_before_last_word_pct']}%) but decides late: SLURP latency p50 {sl['eou']['lat_incl_idle_cpu_ms']['p50']:.0f} ms / p90 {sl['eou']['lat_incl_idle_cpu_ms']['p90']:.0f} ms with a noise-floor tail "
              f"({slz['eou']['lat_incl_idle_cpu_ms']['p50']:.0f} / {slz['eou']['lat_incl_idle_cpu_ms']['p90']:.0f} ms with digital silence), {sl['eou']['miss_pct']}% (SLURP) and {am['eou']['miss_pct']}% (AMI) not decided within 2.5 s, and it is a second always-on streaming model ({T['eou_chunk_ms_160ms_chunks']['p50']:.0f} ms of one thread per 160 ms chunk). The vendor figure (p50 160 ms on TTS audio) is not reproduced on real speech. Keep it as an optional 'cautious' mode."])
lines.append(["Decision agreement (real audio):", f"gold vs ASR transcript on SLURP, scenario level n={sc['n']}: {sc['agree_pct']}% [{sc['agree_wilson95_pct'][0]}, {sc['agree_wilson95_pct'][1]}] -> the >= 97% target is NOT met. Close-talk (headset) {sc['by_condition']['headset']['agree_pct']}%, far-field {sc['by_condition']['far_field']['agree_pct']}%; "
              f"{sc['agree_by_asr_word_errors']['wer_0']['agree_pct']}% when the transcript is exact, {sc['agree_by_asr_word_errors']['wer_3_plus']['agree_pct']}% with 3+ word errors. Accuracy falls {abs(sc['acc_diff_pt'])} pt ({sc['acc_gold_transcript_pct']}% -> {sc['acc_asr_transcript_pct']}%) because ASR WER on SLURP is {S['asr_s560']['wer_pct_vs_gold_transcript']}%."
              + (f" Intent level (60 options, n={it['n']}): agreement {it['agree_pct']}% [{it['agree_wilson95_pct'][0]}, {it['agree_wilson95_pct'][1]}], accuracy {it['acc_gold_transcript_pct']}% -> {it['acc_asr_transcript_pct']}%." if it else "")
              + " The 97% seen on 17 Oct was synthetic Kokoro speech with 5.7% WER; do not quote it for noisy or far-field speech."])
caveats = [
 "Sampling: 500 seeded random utterances per set (s160: first 150 of the same shuffled order; AMI and Earnings-22 got larger independent samples of 2000 and 1500). Intervals are bootstrap over utterances, so they ignore speaker/recording correlation.",
 "dtype: s560 on LibriSpeech test-clean is fp32; the other s560 sets and all s160 are bf16 (AMX) to fit the CPU budget; offline is fp32. bf16 vs fp32 on identical utterances: see the dtype table (WER differences <= 0.07 pt).",
 "Offline mode is compared with the card's 1.12 s column (the card has no fully offline number). The HF offline path is slightly worse than 560 ms streaming on Earnings-22 (139 of 500 utterances worse, 60 better); not investigated further.",
 "Streaming runs one stream per process: transformers' streaming generate does not support a batch of streams (a batched trial returned corrupt text, 1 of 16 identical), so CPU RTFs in the WER tables come from a loaded VM and are only indicative; the idle-VM timings in section 4 are the CPU figures.",
 "TED-LIUM comes from sanchit-gandhi/tedlium-data because the Open-ASR-leaderboard dataset no longer ships tedlium; the 1155-utterance filtering matches the Open-ASR test size. Reference cleanup for TED-LIUM follows the ESB script as I remember it (remove <unk>, re-attach \" '\"); not diffed against that script.",
 "SLURP: audio licence is CC BY-NC 4.0 (the brief says CC BY 4.0, which is true for the text only); used for evaluation only. Gold intent = official scenario_action (60 values, 18 scenarios); the HF copy's own intent column has 18 non-official legacy values and was ignored. Headset/far-field labels are inferred from row order within a slurp_id (supported by the 12.7% vs 21.1% WER gap), not read from file names.",
 "C1 here is the HF reference path on CPU (BF16, torch fallback kernels for the gated delta rule, padding multiple 64), not the L4 SGLang server. The prompt wording and the short scenario descriptions are my construction (no Jev data); other wording would move the absolute accuracy but the gold-vs-ASR comparison uses identical prompts. The 60-option intent level has no descriptions and a smaller n.",
 "End of turn: reference speech end comes from forced alignment (20 ms steps, a few tens of ms of error). Streams are one clip plus a synthetic 2.5 s tail, so false cuts only count pauses inside the clip, not the next speaker. The Smart Turn / VAD state machine is my reading of the pipecat smart-turn repo (VAD stop event -> model on audio since speech start; 3 s silence fallback), not pipecat's own code. VAD needs 0.2 s of speech to start, so AMI backchannels (1-2 words) are often never detected: this limit matters for very short spoken answers.",
 "The first 100 LibriSpeech test-clean clips used to validate the EOU harness are the longest in the file (the dataset is length-sorted), so VAD/Smart Turn rows on that set are not meaningful and are shown only for the EOU check.",
 "Parakeet EOU was converted by us from the .nemo file with the converter functions shipped in transformers (it is the same cache-aware FastConformer-RNNT family); 3.38% WER on 60 LibriSpeech clips shows the weights are intact, but the conversion is not the vendor's own runtime.",
 "Housekeeping: gcp_run.sh once pulled a probe log into c2_build/zed_orch/logs (gcp_r2_probe1.log); I deleted that file. gcp_run.sh also writes its job scripts and logs under ~/jobs on the VM. Everything else is under ~/opt_r2/voice on od-cpu1 (a sibling of other agents' files in ~/opt_r2, which were not touched). I paused (SIGSTOP/SIGCONT) and restarted only my own jobs. od-cpu1 was left running; od-l4b and the production server were never touched.",
]
json.dump({"lines": lines, "caveats": caveats}, open(f"{R}/recommendation.json", "w"), indent=1)
print("wrote recommendation.json")
